mkitem!{mkimpl!{impl < 'tcx > InferCtxt < 'tcx > { # [doc = " Replaces all bound variables (lifetimes, types, and constants) bound by"] # [doc = " `binder` with placeholder variables in a new universe. This means that the"] # [doc = " new placeholders can only be named by inference variables created after"] # [doc = " this method has been called."] # [doc = ""] # [doc = " This is the first step of checking subtyping when higher-ranked things are involved."] # [doc = " For more details visit the relevant sections of the [rustc dev guide]."] # [doc = ""] # [doc = " `fn enter_forall` should be preferred over this method."] # [doc = ""] # [doc = " [rustc dev guide]: https://rustc-dev-guide.rust-lang.org/traits/hrtb.html"] # [instrument (level = "debug" , skip (self) , ret)] pub fn enter_forall_and_leak_universe < T > (& self , binder : ty :: Binder < 'tcx , T >) -> T where T : TypeFoldable < TyCtxt < 'tcx > > , { if ! binder . as_ref () . skip_binder () . has_escaping_bound_vars () { return binder . skip_binder () ; } let next_universe = self . create_next_universe () ; let delegate = FnMutDelegate { regions : & mut | br : ty :: BoundRegion | { ty :: Region :: new_placeholder (self . tcx , ty :: PlaceholderRegion { universe : next_universe , bound : br } ,) } , types : & mut | bound_ty : ty :: BoundTy | { Ty :: new_placeholder (self . tcx , ty :: PlaceholderType { universe : next_universe , bound : bound_ty } ,) } , consts : & mut | bound_const : ty :: BoundConst | { ty :: Const :: new_placeholder (self . tcx , ty :: PlaceholderConst { universe : next_universe , bound : bound_const } ,) } , } ; debug ! (? next_universe) ; self . tcx . replace_bound_vars_uncached (binder , delegate) } # [doc = " Replaces all bound variables (lifetimes, types, and constants) bound by"] # [doc = " `binder` with placeholder variables in a new universe and then calls the"] # [doc = " closure `f` with the instantiated value. The new placeholders can only be"] # [doc = " named by inference variables created inside of the closure `f` or afterwards."] # [doc = ""] # [doc = " This is the first step of checking subtyping when higher-ranked things are involved."] # [doc = " For more details visit the relevant sections of the [rustc dev guide]."] # [doc = ""] # [doc = " This method should be preferred over `fn enter_forall_and_leak_universe`."] # [doc = ""] # [doc = " [rustc dev guide]: https://rustc-dev-guide.rust-lang.org/traits/hrtb.html"] # [instrument (level = "debug" , skip (self , f))] pub fn enter_forall < T , U > (& self , forall : ty :: Binder < 'tcx , T > , f : impl FnOnce (T) -> U) -> U where T : TypeFoldable < TyCtxt < 'tcx > > , { let value = self . enter_forall_and_leak_universe (forall) ; debug ! (? value) ; f (value) } # [doc = " See [RegionConstraintCollector::leak_check][1]. We only check placeholder"] # [doc = " leaking into `outer_universe`, i.e. placeholders which cannot be named by that"] # [doc = " universe."] # [doc = ""] # [doc = " [1]: crate::infer::region_constraints::RegionConstraintCollector::leak_check"] pub fn leak_check (& self , outer_universe : ty :: UniverseIndex , only_consider_snapshot : Option < & CombinedSnapshot < 'tcx > > ,) -> RelateResult < 'tcx , () > { if self . tcx . sess . opts . unstable_opts . no_leak_check || self . skip_leak_check { return Ok (()) ; } self . inner . borrow_mut () . unwrap_region_constraints () . leak_check (self . tcx , outer_universe , self . universe () , only_consider_snapshot ,) } }}}